(() => {
  // [species, length in cm, which]: each species at its smallest and largest
  // weight, and each legendary fish, from the game's own tables
  const { FISH, LEGENDS, lengthFor } = __rhf.data;
  const LIST = [];
  for (const [id, f] of Object.entries(FISH)) LIST.push([id, lengthFor(id, f.min), 'smallest'], [id, lengthFor(id, f.max), 'largest']);
  for (const [k, L] of Object.entries(LEGENDS)) LIST.push([L.base, lengthFor(L.base, L.weight), k]);
  window.__roomCheck = (label) => {
    const g = __rhf.game, v = g.viewmodel, cam = v.camera;
    const ty = Math.tan(cam.fov * Math.PI / 360), tx = ty * cam.aspect;
    const W = innerWidth, H = innerHeight;
    const px = (b) => ({ l: (b.u0 + 1) / 2 * W, r: (b.u1 + 1) / 2 * W, t: (1 - b.v1) / 2 * H, b: (1 - b.v0) / 2 * H });
    const area = (a) => Math.max(0, a.r - a.l) * Math.max(0, a.b - a.t);
    const inter = (a, c) => Math.max(0, Math.min(a.r, c.r) - Math.max(a.l, c.l)) * Math.max(0, Math.min(a.b, c.b) - Math.max(a.t, c.t));
    const R = (r) => ({ l: r.left, r: r.right, t: r.top, b: r.bottom });
    // the card where it rests once it has slid in, as the game measures it
    const cardEl = document.getElementById('catch');
    const sliding = cardEl.getAnimations().length > 0;
    if (sliding) cardEl.style.animation = 'none';
    const card = R(cardEl.getBoundingClientRect());
    if (sliding) cardEl.style.animation = '';
    const sa = R(g.hud.safeArea.getBoundingClientRect());
    const bars = g.hud.topBars.map((e) => R(e.getBoundingClientRect())).filter((r) => r.r > r.l && r.b > r.t);
    const c = g.photo.crop();
    const crop = { l: W * (1 - c.fx) / 2, r: W * (1 + c.fx) / 2, t: H * (1 - c.fy) / 2, b: H * (1 + c.fy) / 2 };
    const cardN = { x0: card.l / W * 2 - 1, x1: card.r / W * 2 - 1, y0: 1 - card.b / H * 2, y1: 1 - card.t / H * 2 };
    const hideCard = (u, w) => u < -1 || u > 1 || w < -1 || w > 1 || (u > cardN.x0 && u < cardN.x1 && w > cardN.y0 && w < cardN.y1);
    const hidePhoto = (u, w) => Math.abs(u) > c.fx || Math.abs(w) > c.fy;
    const pct = (x, b) => Math.round(1000 * x / Math.max(1, area(b))) / 10;
    const n = { old: 0, oldWorst: 0, card: 0, cardWorst: 0, off: 0, bars: 0, ends: 0, endsPhoto: 0, photo: 0, photoWorst: 0, far: 1, farPhoto: 1 };
    const bad = [];
    for (const [id, len, tag] of LIST) {
      v.showFish(id, len);
      const d0 = v.fishD0;
      // the open ends of the two sleeves, in the rig's frame as it is held
      const ends = [];
      for (const arm of v.fishHands) {
        if (!arm.visible) continue;
        const pos = arm.children[1].geometry.attributes.position;
        const P = arm.position.clone();
        let far = -Infinity;
        const pts = [];
        for (let i = 0; i < pos.count; i++) {
          P.fromBufferAttribute(pos, i);
          const k = P.y * -0.62 + P.z * 0.72;
          pts.push([P.x, P.y, P.z, k]);
          if (k > far) far = k;
        }
        const tilt = v.fishRig.rotation.clone().set(0.1, 0, 0);
        for (const q of pts) if (q[3] > far - 0.015) ends.push(P.set(q[0], q[1], q[2]).add(arm.position).applyEuler(tilt).clone());
      }
      const seen = (x, y, d, hide) => ends.filter((e) => !hide((x + e.x) / ((d - e.z) * tx), (y + e.y) / ((d - e.z) * ty))).length;
      const old = px(v.fishSpan(0.02, -0.1, d0, tx, ty));
      const f = { ...v.fishFit(g.hud.catchRoom) };
      const a = px(v.fishSpan(f.x, f.y, f.d, tx, ty));
      const p = { ...v.fishFit(v.photoRoom()) };
      const pb = px(v.fishSpan(p.x, p.y, p.d, tx, ty));
      const o = pct(inter(old, card), old);
      if (o > 0) { n.old++; n.oldWorst = Math.max(n.oldWorst, o); }
      const u = pct(inter(a, card), a);
      if (u > 0) { n.card++; n.cardWorst = Math.max(n.cardWorst, u); }
      const off = pct(area(a) - inter(a, sa), a);
      if (off > 0) n.off++;
      const b = pct(bars.reduce((s, r) => s + inter(a, r), 0), a);
      if (b > 0) n.bars++;
      const e1 = seen(f.x, f.y, f.d, hideCard);
      const e2 = seen(p.x, p.y, p.d, hidePhoto);
      if (e1) n.ends++;
      if (e2) n.endsPhoto++;
      const cut = pct(area(pb) - inter(pb, crop), pb);
      if (cut > 0) { n.photo++; n.photoWorst = Math.max(n.photoWorst, cut); }
      n.far = Math.max(n.far, f.d / d0);
      n.farPhoto = Math.max(n.farPhoto, p.d / d0);
      if (u > 0 || off > 0 || b > 0 || e1 || e2 || cut > 0) bad.push(`${id} ${len} cm (${tag}): card ${u}%, off ${off}%, bars ${b}%, sleeve ends ${e1}/${e2}, photo cut ${cut}%`);
    }
    // the king salmon back in hand for the picture
    v.showFish('king', 110);
    const ok = n.card === 0 && n.off === 0 && n.bars === 0 && n.ends === 0 && n.endsPhoto === 0 && n.photo === 0;
    return `${ok ? 'PASS' : 'FAIL'} ${label} ${W}x${H}, ${LIST.length} fish: under the card ${n.card} (at the old place ${n.old}, worst ${n.oldWorst}%), off the safe area ${n.off}, under the top bars ${n.bars}, sleeve ends in sight ${n.ends} (photo ${n.endsPhoto}), photo frame cuts ${n.photo} (worst ${n.photoWorst}%), held out at most ${n.far.toFixed(2)}x (photo ${n.farPhoto.toFixed(2)}x)` + (bad.length ? ' | ' + bad.join('; ') : '');
  };
  return 'check ready, ' + LIST.length + ' fish';
})()
